#!/usr/bin/env python3
# luxarch:ledger hook v13 - DO NOT edit this file - it is emitted by `luxarch --emit hooks`; re-emit to update.
"""Shared helpers for the commit-ledger hooks (record / stop-guard / clear)."""

from __future__ import annotations

import contextlib
import hashlib
import http.client
import importlib
import json
import os
import re
import shutil
import signal
import subprocess
import sys
import tempfile
import threading
import time
import urllib.parse
from collections.abc import Callable, Iterator
from pathlib import Path
from types import FrameType, ModuleType

_FCNTL: ModuleType | None
try:
    import fcntl as _fcntl_module

    _FCNTL = _fcntl_module
except ImportError:  # not POSIX: the atomic replace still holds, the lock does not
    _FCNTL = None


def project_dir() -> Path:
    d = os.environ.get("CLAUDE_PROJECT_DIR")
    if d:
        return Path(d)
    try:
        return Path(
            subprocess.check_output(
                ["git", "rev-parse", "--show-toplevel"],
                text=True,
                stderr=subprocess.DEVNULL,
            ).strip()
        )
    except Exception:
        return Path.cwd()


def tree_dir() -> Path:
    """The checkout the agent is working in: the top of the event's `cwd`, else the project dir.

    An agent works in its issue's worktree (`<repo parent>/.worktrees/<repo>/<ISSUE-KEY>`, --doc
    FLEET-AGENT-CONDUCT-STANDARD, "Concurrent agents: one worktree per issue") while
    CLAUDE_PROJECT_DIR can still name the main checkout, so a `git rev-parse HEAD` run there
    recorded the main checkout's HEAD, not the commit just made."""
    cwd = str(_EVENT.get("cwd") or "")
    if cwd:
        try:
            top = subprocess.check_output(
                ["git", "-C", cwd, "rev-parse", "--show-toplevel"],
                text=True,
                stderr=subprocess.DEVNULL,
            ).strip()
        except Exception:
            top = ""
        if top:
            return Path(top)
    return project_dir()


def state_dir() -> Path:
    """Where session state lives: `.claude/` in the MAIN checkout, shared by every worktree.

    A worktree is removed when its issue lands, and the ledger must outlive it: the commits it
    recorded still have to be logged to LuxPM and pushed from the main checkout."""
    try:
        common = subprocess.check_output(
            [
                "git",
                "-C",
                str(tree_dir()),
                "rev-parse",
                "--path-format=absolute",
                "--git-common-dir",
            ],
            text=True,
            stderr=subprocess.DEVNULL,
        ).strip()
    except Exception:
        common = ""
    if common and Path(common).name == ".git":
        return Path(common).parent / ".claude"
    return project_dir() / ".claude"


def ledger_path() -> Path:
    return state_dir() / ".luxpm-ledger.json"


# ── Shared state, safe under concurrent sessions ────────────────────────────────────────────────
# Every session's hooks read, change and write the same files here. Each change is made under an
# exclusive lock on a sidecar `<file>.lock` (so two writers never drop each other's entry), and
# written to a temporary file in the same directory that replaces the real one in one step (so a
# reader never sees half a file). A file that exists but does not parse is kept aside as
# `<file>.unreadable-<time>` rather than overwritten, and a reader that must not guess (the Stop
# guard) is told it is unreadable instead of reading it as empty.


class Unreadable(ValueError):
    """A state file exists but cannot be read as the JSON it should hold."""


@contextlib.contextmanager
def _locked(path: Path) -> Iterator[None]:
    path.parent.mkdir(parents=True, exist_ok=True)
    with open(str(path) + ".lock", "a", encoding="utf-8") as fh:
        if _FCNTL is not None:
            _FCNTL.flock(fh.fileno(), _FCNTL.LOCK_EX)
        try:
            yield
        finally:
            if _FCNTL is not None:
                _FCNTL.flock(fh.fileno(), _FCNTL.LOCK_UN)


def _write_atomic(path: Path, text: str) -> None:
    fd, tmp = tempfile.mkstemp(
        dir=str(path.parent), prefix=f".{path.name}.", suffix=".tmp"
    )
    try:
        with os.fdopen(fd, "w", encoding="utf-8") as fh:
            fh.write(text)
            fh.flush()
            os.fsync(fh.fileno())
        os.replace(tmp, path)
    except BaseException:
        with contextlib.suppress(OSError):
            os.unlink(tmp)
        raise


def _read_json(path: Path, default: object) -> object:
    """The file's JSON, `default` when it does not exist; Unreadable when it exists and won't parse."""
    try:
        text = path.read_text(encoding="utf-8")
    except FileNotFoundError:
        return default
    except OSError as exc:
        raise Unreadable(f"{path}: {exc}") from exc
    try:
        return json.loads(text)
    except _PAYLOAD_ERRORS as exc:
        raise Unreadable(f"{path}: {exc.__class__.__name__}") from exc


def _update_json(
    path: Path, default: object, change: Callable[[object], object]
) -> object:
    """Read, change and write `path` as one step no other session can interleave with."""
    with _locked(path):
        try:
            data = _read_json(path, default)
        except Unreadable:
            path.replace(path.with_name(f"{path.name}.unreadable-{int(time.time())}"))
            data = default
        new = change(data)
        _write_atomic(path, json.dumps(new, indent=2))
        return new


def _entries(data: object) -> list[dict[str, object]]:
    return [e for e in data if isinstance(e, dict)] if isinstance(data, list) else []


def read_ledger(strict: bool = False) -> list[dict[str, object]]:
    """The LuxPM ledger. With `strict`, a ledger that exists but cannot be read raises Unreadable
    (a Stop guard must not read it as empty); otherwise it reads as empty."""
    try:
        return _entries(_read_json(ledger_path(), []))
    except Unreadable:
        if strict:
            raise
        return []


def update_ledger(
    change: Callable[[list[dict[str, object]]], list[dict[str, object]]],
) -> list[dict[str, object]]:
    """Change the LuxPM ledger as one locked step: `change` gets the entries and returns the new ones."""
    return _entries(_update_json(ledger_path(), [], lambda d: change(_entries(d))))


def write_ledger(entries: list[dict[str, object]]) -> None:
    update_ledger(lambda _old: entries)


def git(*args: str) -> str:
    return git_at(tree_dir(), *args)


def git_at(where: Path, *args: str) -> str:
    """`git -C <where> <args>`'s output, or '' when it fails."""
    try:
        return subprocess.check_output(
            ["git", "-C", str(where), *args],
            text=True,
            stderr=subprocess.DEVNULL,
        ).strip()
    except Exception:
        return ""


def event_cwd() -> Path:
    """The shell's directory for this event (where a `git -C <rel>` is relative to)."""
    cwd = str(read_event().get("cwd") or "")
    return Path(cwd) if cwd else tree_dir()


def session_id() -> str:
    """This agent session's id, from the hook payload if it was read, else the env.

    Claude Code puts `session_id` in every hook event. `read_event()` caches it so a hook that has
    already consumed stdin can still ask. Empty string when unavailable — entries written without a
    session are treated as everyone's, which keeps a pre-upgrade ledger from being ignored.
    """
    # str() at the boundary: the payload is untyped JSON, and an id is only ever compared
    # as a string.
    return str(_EVENT.get("session_id") or os.environ.get("CLAUDE_SESSION_ID", ""))


# A NAMED tuple, not an inline `except (OSError, ValueError)`. Under `target = "py314"` ruff
# formats the inline form to PEP 758's `except OSError, ValueError:`; under py311/py313 it keeps the
# parentheses. So the SAME emitted file has two canonical forms, and an emitted asset is supposed to
# be byte-identical everywhere — in a py314 repo `luxlint --format` rewrote it, `repo.hooks_current`
# then reported drift, and the two guards DEADLOCKED with no local fix.
#
# The fleet declares three targets today (4 guards py311, 7 repos py313, 14 repos py314), so an
# emitted asset must avoid every construct whose canonical formatting is target-dependent. A NAME has
# no parentheses for a formatter to take away.
_PAYLOAD_ERRORS = (OSError, ValueError, RecursionError)

_EVENT: dict[str, object] = {}


def read_event() -> dict[str, object]:
    """Parse the hook event from stdin ONCE and cache it (stdin can only be read once)."""
    global _EVENT
    if not _EVENT:
        try:
            data = json.load(sys.stdin)
        except _PAYLOAD_ERRORS:
            # Only a missing/malformed payload is tolerated. A bare `except Exception` here hid a
            # NameError (an unimported `sys`) as "no event", so record-commit silently recorded
            # NOTHING while exiting 0 — the same shape as the settings.json data loss.
            data = None
        # A payload that is JSON but not an object (a list, a number) is as unreadable as one
        # that is not JSON: every caller reads it with `.get`.
        _EVENT = data if isinstance(data, dict) else {}
    return _EVENT


def event_command() -> str:
    """The Bash command this event carries; '' when there is none or it is not text."""
    ti = read_event().get("tool_input")
    cmd = ti.get("command") if isinstance(ti, dict) else None
    return cmd if isinstance(cmd, str) else ""


def mine(entries: list[dict[str, object]]) -> list[dict[str, object]]:
    """The ledger entries belonging to THIS session.

    An entry with no session is included: it predates session stamping, so holding the current agent
    to it is the conservative choice. An entry stamped with a DIFFERENT session is another agent's
    work — it must not block this one, and this one must not log it (that would put wrong commits on
    someone else's ticket).
    """
    me = session_id()
    return [e for e in entries if not e.get("session") or e.get("session") == me]


def others(entries: list[dict[str, object]]) -> list[dict[str, object]]:
    me = session_id()
    return [e for e in entries if e.get("session") and e.get("session") != me]


# ── the LuxPM search marker ───────────────────────────────────────────────────────────────────────────
# A PostToolUse hook records "this session searched LuxPM" the moment a search RETURNS; the
# search-before-create hook reads it. Reading the transcript alone raced Claude Code's flush: the
# search that ran one call earlier was not in the file yet when the create was judged, so 4 of 11
# creates after a search were denied in one session.


def search_marker_path() -> Path:
    return state_dir() / ".luxpm-searched.json"


def _marker(data: object) -> dict[str, bool]:
    return {str(k): bool(v) for k, v in data.items()} if isinstance(data, dict) else {}


def _read_marker() -> dict[str, bool]:
    try:
        return _marker(_read_json(search_marker_path(), {}))
    except Unreadable:
        return {}


def mark_searched() -> None:
    sid = session_id()
    _update_json(search_marker_path(), {}, lambda d: {**_marker(d), sid: True})


def clear_searched() -> None:
    sid = session_id()
    _update_json(
        search_marker_path(),
        {},
        lambda d: {k: v for k, v in _marker(d).items() if k != sid},
    )


def has_searched() -> bool:
    return _read_marker().get(session_id(), False)


# ── what each session searched LuxPM FOR (v6) ─────────────────────────────────────────────────────────
# edit-history needs the terms, not just the fact: the first change to a file is allowed once this
# session has searched LuxPM for that file, because a hold on it lives in LuxPM, not in git.


def search_terms_path() -> Path:
    return state_dir() / ".luxpm-search-terms.json"


def _terms(data: object) -> dict[str, list[str]]:
    if not isinstance(data, dict):
        return {}
    return {
        str(k): [t for t in v if isinstance(t, str)]
        for k, v in data.items()
        if isinstance(v, list)
    }


def _read_terms(path: Path) -> dict[str, list[str]]:
    try:
        return _terms(_read_json(path, {}))
    except Unreadable:
        return {}


def _record_term(path: Path, term: str) -> bool:
    """Add `term` to this session's list in `path`. False when it cannot be written."""
    term, sid = term.strip(), session_id()
    if not term or not sid:
        return False

    def add(data: object) -> dict[str, list[str]]:
        terms = _terms(data)
        mine = terms.get(sid, [])
        terms[sid] = (mine if term in mine else [*mine, term])[-1000:]
        return terms

    try:
        _update_json(path, {}, add)
    except OSError:
        return False
    return True


def _writable(p: Path) -> bool:
    try:
        p.parent.mkdir(parents=True, exist_ok=True)
        if p.exists():
            return p.is_file() and os.access(p, os.W_OK)
        return os.access(p.parent, os.W_OK)
    except OSError:
        return False


def record_search_term(term: str) -> bool:
    """Remember a LuxPM search term for this session. False when it cannot be written."""
    return _record_term(search_terms_path(), term)


def search_terms() -> list[str]:
    return _read_terms(search_terms_path()).get(session_id(), [])


def terms_writable() -> bool:
    """Can a search term be remembered here? A gate that waits for one must not wait forever."""
    return _writable(search_terms_path())


# ── what each session's path searches found ───────────────────────────────────────────────────────
# `luxpm_list_issues(path=<file>)` lists the open issues whose `files`, text or linked commits name the
# file or a directory above it, each with its state and labels. luxpm-search-mark records every page
# it reads here, and edit-history judges from it whether the result was read whole and which of its
# issues may hold the file; the agent reads each possible hold's waiting_on.

CLOSED_STATES = ("done", "cancelled")
ESCALATION_LABEL = "fleet-escalation"
WORK_ORDER_LABEL = "work-order"
_NORM_ERRORS = (ValueError, OSError)
_GIT_ERRORS = (OSError, subprocess.SubprocessError)

Issue = dict[str, object]
# first and last result shown, whether more exist, and the order the page was listed in ('' when
# the call fixed none)
Page = tuple[int, int, bool, str]
# one page read: its Page and the keys listed on it, in order
Read = tuple[int, int, bool, str, tuple[str, ...]]
# The one order a result of several pages is read in: by issue number, which is unique in a
# project, ascending. `created_at` ties (issues made in one transaction) list in any order.
PAGE_ORDER = "sequence_id:asc"
# a key whose number cannot be read (`AB-x`, `AB`)
_KEY_ERRORS = (IndexError, ValueError)
_READS_KEPT = 400


def path_searches_path() -> Path:
    return state_dir() / ".luxpm-path-searches.json"


def hold_notices_path() -> Path:
    return state_dir() / ".luxpm-hold-notices.json"


def norm_path(raw: str, root: Path | None = None) -> str:
    """A searched path as a repo-relative POSIX path ('' when it names no path in the checkout)."""
    p = raw.strip().replace("\\", "/")
    if p.startswith("/"):
        try:
            p = Path(p).resolve().relative_to((root or tree_dir()).resolve()).as_posix()
        except _NORM_ERRORS:
            return ""
    p = os.path.normpath(p).replace("\\", "/") if p else ""
    if p in ("", ".", "..") or p.startswith("../"):
        return ""
    return p


def _issue(v: object) -> Issue | None:
    if not isinstance(v, dict) or not isinstance(v.get("key"), str):
        return None
    labels = v.get("labels")
    return {
        "key": str(v["key"]),
        "state": str(v.get("state") or ""),
        "waiting": str(v.get("waiting") or ""),
        "labels": [x for x in labels if isinstance(x, str)]
        if isinstance(labels, list)
        else [],
    }


def _read(v: object) -> Read | None:
    if not isinstance(v, list) or len(v) != 5:
        return None
    first, last, more, order, keys = v
    if (
        isinstance(first, int)
        and isinstance(last, int)
        and isinstance(more, bool)
        and isinstance(order, str)
        and isinstance(keys, list)
        and all(isinstance(k, str) for k in keys)
    ):
        return (first, last, more, order, tuple(keys))
    return None


class PathSearch:
    """One searched path: the pages of its result read so far, in the order read, and the issues
    on them (each issue as its newest read listed it)."""

    def __init__(self, reads: list[Read], issues: list[Issue]) -> None:
        self.reads = reads
        self.issues = issues

    @classmethod
    def load(cls, v: object) -> PathSearch:
        d = v if isinstance(v, dict) else {}
        reads, issues = d.get("reads"), d.get("issues")
        found = (
            [i for x in issues if (i := _issue(x))] if isinstance(issues, list) else []
        )
        if reads is None and isinstance(d.get("pages"), list) and len(d["pages"]) == 1:
            # a record the previous version wrote: one page that ends the results is one read
            old = d["pages"][0]
            if (
                isinstance(old, list)
                and len(old) == 4
                and old[0] == 1
                and old[2] is False
                and isinstance(old[1], int)
            ):
                keys = [str(i.get("key")) for i in found]
                reads = [[1, old[1], False, "", keys]]
        return cls(
            [r for x in reads if (r := _read(x))] if isinstance(reads, list) else [],
            found,
        )

    def dump(self) -> dict[str, object]:
        return {
            "reads": [[*r[:4], list(r[4])] for r in self.reads],
            "issues": self.issues,
        }

    def restarts(self, page: Page) -> bool:
        """A first page starts the result afresh."""
        return page[0] <= 1

    def chain_ok(self) -> bool:
        """The reads so far are one overlapping chain from the first result: each next page starts
        on the previous page's last row (offset = its last - 1), in issue-number order, and opens
        with that same issue. An issue that closes, reopens or starts naming the path before the
        boundary between two reads moves the boundary row, so the overlap no longer matches."""
        r = self.reads
        if not r or r[0][0] > 1:
            return False
        if len(r) == 1:
            return True
        if any(x[3] != PAGE_ORDER for x in r):
            return False
        for i in range(1, len(r)):
            a, b = r[i - 1], r[i]
            if not a[2] or not a[4] or not b[4] or b[0] != a[1] or b[4][0] != a[4][-1]:
                return False
        seq = list(r[0][4]) + [k for x in r[1:] for k in x[4][1:]]
        try:
            nums = [int(k.rsplit("-", 1)[1]) for k in seq]
        except _KEY_ERRORS:
            return False
        return all(nums[i - 1] < nums[i] for i in range(1, len(nums)))

    def whole(self) -> bool:
        """The result was read whole: one page from the first result that ends the results, or
        an overlapping chain of pages (`chain_ok`) from the first to one that ends them."""
        return self.chain_ok() and not self.reads[-1][2]

    def next_offset(self) -> int:
        """The `offset` of the next page to read: one row back from the last page read, while the
        chain holds; 0 (start again) when it does not."""
        if (
            self.chain_ok()
            and self.reads[-1][2]
            and (len(self.reads) > 1 or self.reads[0][3] == PAGE_ORDER)
        ):
            return self.reads[-1][1] - 1
        return 0

    def _open(self, own_key: str) -> list[Issue]:
        """Each open issue that is neither this worktree's own nor a work order (an index of
        other issues, which holds nothing itself)."""
        out: list[Issue] = []
        for i in self.issues:
            raw = i.get("labels")
            labels = [str(x) for x in raw] if isinstance(raw, list) else []
            if (
                str(i.get("state")) in CLOSED_STATES
                or str(i.get("key")) == own_key
                or WORK_ORDER_LABEL in labels
            ):
                continue
            out.append(i)
        return out

    def holds(self, own_key: str) -> list[Issue]:
        """The issues that hold the code: an open escalation, or any issue on_hold. Whom a park
        waits on is free text that can name anyone, and an agent parks only on a question to the
        owner, so every on_hold holds: the denial prints its waiting_on, once, for the agent to
        read, and the agent retries past one that is about other code or is its own work."""
        out: list[Issue] = []
        for i in self._open(own_key):
            labels = i.get("labels")
            held = str(i.get("state")) == "on_hold"
            if held or (isinstance(labels, list) and ESCALATION_LABEL in labels):
                out.append(i)
        return out

    def in_progress(self, own_key: str) -> list[str]:
        """Keys of the issues in progress elsewhere: advice, never a hold. Every fleet agent
        posts as one LuxPM user, so whose work it is cannot be read from the issue."""
        return [
            str(i.get("key"))
            for i in self._open(own_key)
            if str(i.get("state")) == "in_progress"
        ]


def hold_line(i: Issue) -> str:
    """`KEY (state, open escalation; waiting on: <text>)` for a hold."""
    labels = i.get("labels")
    what = [str(i.get("state"))]
    if isinstance(labels, list) and ESCALATION_LABEL in labels:
        what.append("open escalation")
    waiting = str(i.get("waiting") or "")
    return f"{i.get('key')} ({', '.join(what)}" + (
        f"; waiting on: {waiting})" if waiting else ")"
    )


def _searched_paths(data: object) -> dict[str, dict[str, object]]:
    """{session: {path: <PathSearch dump>}}, with anything malformed dropped."""
    if not isinstance(data, dict):
        return {}
    return {
        str(sid): {str(p): rec for p, rec in paths.items() if isinstance(rec, dict)}
        for sid, paths in data.items()
        if isinstance(paths, dict)
    }


def record_path_page(path: str, page: Page, issues: list[Issue]) -> bool:
    """Record one page of a path search for this session. A first page starts that path's record
    afresh (the newest search of it is what LuxPM says now, so a hold lifted since drops out); it
    never touches another path's record."""
    sid = session_id()
    if not sid or not path:
        return False

    def add(data: object) -> dict[str, dict[str, object]]:
        everyone = _searched_paths(data)
        mine = everyone.get(sid, {})
        old = mine.pop(path, None)
        rec = PathSearch.load(old)
        if old is None or rec.restarts(page):
            rec = PathSearch([], [])
        keys = tuple(str(i.get("key")) for i in issues)
        rec.reads = [*rec.reads, (*page, keys)]
        if len(rec.reads) > _READS_KEPT:  # the chain needs its first read
            rec.reads = [rec.reads[0], *rec.reads[-(_READS_KEPT - 1) :]]
        rec.issues = [i for i in rec.issues if str(i.get("key")) not in keys] + issues
        mine[path] = rec.dump()
        everyone[sid] = dict(list(mine.items())[-300:])
        return everyone

    try:
        _update_json(path_searches_path(), {}, add)
    except OSError:
        return False
    return True


def forget_path(path: str) -> bool:
    """A result for `path` this hook could not read: its record is emptied, never kept, so an
    older whole read of it no longer clears the file and a text search cannot either."""
    sid = session_id()
    if not sid or not path:
        return False

    def drop(data: object) -> dict[str, dict[str, object]]:
        everyone = _searched_paths(data)
        mine = everyone.get(sid, {})
        mine.pop(path, None)
        mine[path] = PathSearch([], []).dump()
        everyone[sid] = dict(list(mine.items())[-300:])
        return everyone

    try:
        _update_json(path_searches_path(), {}, drop)
    except OSError:
        return False
    return True


def path_searches() -> dict[str, PathSearch]:
    """This session's path searches, by searched path."""
    try:
        data = _read_json(path_searches_path(), {})
    except Unreadable:
        return {}
    mine = _searched_paths(data).get(session_id(), {})
    return {p: PathSearch.load(rec) for p, rec in mine.items()}


def covering_searches(rel: str, searched: dict[str, PathSearch]) -> list[str]:
    """Every searched path that is `rel` or a directory above it, most specific first."""
    over = [p for p in searched if rel == p or rel.startswith(p + "/")]
    return sorted(over, key=len, reverse=True)


def hold_noticed(where: str, holds: list[str]) -> bool:
    """Has this session already been shown exactly these hold lines on `where`?"""
    try:
        data = _read_json(hold_notices_path(), {})
    except Unreadable:
        return False
    mine = data.get(session_id()) if isinstance(data, dict) else None
    seen = mine.get(where) if isinstance(mine, dict) else None
    return isinstance(seen, list) and sorted(holds) in seen


def record_hold_notice(where: str, holds: list[str]) -> bool:
    """Remember that this session was shown these hold lines on `where`. False when it cannot be
    written (then the next change is denied again: a notice not remembered is shown again)."""
    sid = session_id()
    if not sid:
        return False

    def add(data: object) -> dict[str, object]:
        everyone = dict(data) if isinstance(data, dict) else {}
        raw = everyone.get(sid)
        mine = {str(k): v for k, v in raw.items()} if isinstance(raw, dict) else {}
        old = mine.pop(where, [])
        seen = [s for s in old if isinstance(s, list)] if isinstance(old, list) else []
        mine[where] = [*seen, sorted(holds)][-20:]
        everyone[sid] = dict(list(mine.items())[-300:])
        return everyone

    try:
        _update_json(hold_notices_path(), {}, add)
    except OSError:
        return False
    return True


def repo_project(root: Path) -> str:
    """This repo's LuxPM project code, from the `project:` line of its committed `.luxpm-receipt`
    (the sync receipt `/wrap-up` writes), else ''."""
    try:
        text = (root / ".luxpm-receipt").read_text(encoding="utf-8")
    except _NORM_ERRORS:
        return ""
    for line in text.splitlines()[:40]:
        if line.startswith("project:"):
            return line.split(":", 1)[1].strip().upper()
    return ""


# ── state no agent tool writes: the wait after `/fleet-start` and the owner's notes ─────────────────
# Kept under `~/.claude/luxarch-state/<checkout id>/`, outside every checkout: the shared-machine hook
# denies an agent's writes outside its worktree and its scratch, so only these hooks write here.
# `gate/<session>` exists while the session waits for the owner's go-ahead; `orders/<session>.json`
# holds each `/fleet-start <note>` the owner typed, as `{note, at}`, printed back at every
# `/fleet-start` and after every compact.
OWNER_ORDER_LABEL = "owner-order"
_SAFE_NAME = re.compile(r"[A-Za-z0-9][A-Za-z0-9_.-]{0,127}")


def private_state_home() -> Path:
    """`~/.claude/luxarch-state/<sha256 of the main checkout's path, first 16>/`."""
    main = str(state_dir().parent.resolve())
    home = os.environ.get("HOME") or str(Path.home())
    digest = hashlib.sha256(main.encode("utf-8")).hexdigest()[:16]
    return Path(home) / ".claude" / "luxarch-state" / digest


def _session_file(sid: str) -> str:
    """The session id as a file name: itself when it is a plain name, else its hash."""
    if _SAFE_NAME.fullmatch(sid) and sid not in (".", ".."):
        return sid
    return "h-" + hashlib.sha256(sid.encode("utf-8")).hexdigest()[:32]


def gate_path(sid: str) -> Path:
    return private_state_home() / "gate" / _session_file(sid)


def orders_path(sid: str) -> Path:
    return private_state_home() / "orders" / f"{_session_file(sid)}.json"


_GATE_MARK = "waiting\n"


def gate_waiting(sid: str) -> tuple[bool, str]:
    """(waiting, why the state is corrupt or ''). No session or no file: not waiting. A file that
    exists and cannot be read as the mark: waiting, and corrupt."""
    if not sid:
        return False, ""
    path = gate_path(sid)
    try:
        text = path.read_text(encoding="utf-8")
    except FileNotFoundError:
        return False, ""
    except _PAYLOAD_ERRORS as exc:
        return True, f"{path}: {exc.__class__.__name__}"
    if text != _GATE_MARK:
        return True, f"{path}: unexpected content"
    return True, ""


def set_gate(sid: str, waiting: bool) -> None:
    """Open (waiting) or close this session's wait."""
    if not sid:
        return
    path = gate_path(sid)
    if waiting:
        path.parent.mkdir(parents=True, exist_ok=True)
        _write_atomic(path, _GATE_MARK)
        return
    if path.is_dir() and not path.is_symlink():
        shutil.rmtree(path)
        return
    with contextlib.suppress(FileNotFoundError):
        path.unlink()


# A `/fleet-start` the owner typed: the WHOLE prompt is the command, plain or as Claude Code's tags
# (an optional `<command-message>`, the `<command-name>` and an optional `<command-args>`, with only
# whitespace between). A tag pasted inside a longer prompt is no command.
_START_PLAIN = re.compile(r"\s*/fleet-start(?:\s+(?P<note>\S.*?))?\s*", re.DOTALL)
_MESSAGE = r"<command-message>[^<]*</command-message>\s*"
_START_TAGGED = re.compile(
    rf"\s*(?:{_MESSAGE})?<command-name>/fleet-start</command-name>\s*(?:{_MESSAGE})?"
    r"(?:<command-args>(?P<note>.*?)</command-args>\s*)?(?:" + _MESSAGE + r")?",
    re.DOTALL,
)


def start_note(prompt: str) -> str | None:
    """The note of a prompt that is, whole, a `/fleet-start` ('' for none); None for any other."""
    m = _START_PLAIN.fullmatch(prompt) or _START_TAGGED.fullmatch(prompt)
    if not m:
        return None
    return (m.group("note") or "").strip()


# An envelope Claude Code wraps around what is not the owner's typing: a task notification, a
# system reminder. A prompt that opens with one is not the owner speaking.
_ENVELOPE = re.compile(r"\s*<[A-Za-z][\w-]*[\s>/]")


# A slash command the owner typed, as Claude Code's tags: the WHOLE prompt is the command.
_COMMAND_TAGGED = re.compile(
    rf"\s*(?:{_MESSAGE})?<command-name>/[A-Za-z0-9][\w:.-]*</command-name>\s*(?:{_MESSAGE})?"
    r"(?:<command-args>.*?</command-args>\s*)?(?:" + _MESSAGE + r")?",
    re.DOTALL,
)


def owner_spoke(prompt: str) -> bool:
    """The prompt is the owner's own message: not empty, and not opening with an envelope tag,
    or, whole, a slash command the owner typed (Claude Code sends it in tags)."""
    if _COMMAND_TAGGED.fullmatch(prompt):
        return True
    return bool(prompt.strip()) and not _ENVELOPE.match(prompt)


def _notes(data: object) -> list[dict[str, str]]:
    if not isinstance(data, list):
        return []
    return [
        {"note": str(o["note"]), "at": str(o.get("at") or "")}
        for o in data
        if isinstance(o, dict) and isinstance(o.get("note"), str)
    ]


def record_note(note: str) -> bool:
    """Append the note of a `/fleet-start <note>` the owner typed to this session's record."""
    sid = session_id()
    if not sid or not note.strip():
        return False
    at = time.strftime("%Y-%m-%dT%H:%M:%SZ", time.gmtime())
    try:
        _update_json(
            orders_path(sid),
            [],
            lambda d: [*_notes(d), {"note": note, "at": at}][-200:],
        )
    except OSError:
        return False
    return True


def keys_path(sid: str) -> Path:
    return private_state_home() / "keys" / f"{_session_file(sid)}.json"


def record_owner_keys(prompt: str) -> bool:
    """Remember each issue key in a prompt the owner typed this session (a relayed escalation's
    key comes from the owner, never from the agent)."""
    sid = session_id()
    keys = sorted(set(re.findall(r"\b[A-Z][A-Z0-9]{1,15}-\d+\b", prompt)))
    if not sid or not keys:
        return False

    def add(d: object) -> list[str]:
        old = [str(k) for k in d] if isinstance(d, list) else []
        return sorted(set(old) | set(keys))[-2000:]

    try:
        _update_json(keys_path(sid), [], add)
    except OSError:
        return False
    return True


def owner_keys() -> set[str]:
    """The issue keys the owner typed this session (empty when none or unreadable)."""
    sid = session_id()
    if not sid:
        return set()
    try:
        data = _read_json(keys_path(sid), [])
    except _PAYLOAD_ERRORS:
        return set()
    return {str(k) for k in data} if isinstance(data, list) else set()


def owner_notes() -> list[dict[str, str]]:
    """This session's `/fleet-start` notes, oldest first ([] when none or unreadable)."""
    sid = session_id()
    if not sid:
        return []
    try:
        return _notes(_read_json(orders_path(sid), []))
    except _PAYLOAD_ERRORS:
        return []


# ── whom a parked issue waits on ─────────────────────────────────────────────────────────────────
# An agent parks an issue only on a question to the owner: `on_hold` with
# `waiting_on: "owner: <the question?>"`. Every other park is the agent's own work set aside.
GUARDS = ("luxarch", "luxlint", "luxaudit", "luxios")
_OWNER_QUESTION = re.compile(r"owner: .*\?\s*", re.DOTALL)
OWNER_QUESTION_FORM = '`waiting_on: "owner: <the question?>"`'


def owner_question(raw: object) -> bool:
    """This waiting_on is, whole, a question to the owner: `owner: …?`."""
    return isinstance(raw, str) and bool(_OWNER_QUESTION.fullmatch(raw.strip()))


# ── LuxPM itself: the issues a hook judges, read from LuxPM, never from the transcript ─────────────
# A hook asks LuxPM's own MCP endpoint for the issues it judges (`luxpm_get_context`, one POST), with
# the connection Claude Code uses for LuxPM in this project: the `luxpm` server of type `http` in
# its local scope (`~/.claude.json`, `projects.<checkout>.mcpServers`), its project scope (the
# checkout's `.mcp.json`, `${VAR}` and `${VAR:-default}` expanded from the environment), or its
# user scope (`~/.claude.json`, `mcpServers`), first found. With no such server, or a LuxPM that
# does not answer, the hook knows nothing of the issue, and says so.
_LUXPM_TIMEOUT = 10
# every LuxPM call of one hook run finishes inside this many seconds, or the run denies: far
# inside Claude Code's hook timeout (60 s), past which a hook stops blocking at all
_LUXPM_DEADLINE = 20.0
_NOT_FOUND = re.compile(r"\bnot\s+found\b", re.IGNORECASE)
_LUXPM_ERRORS = (OSError, ValueError, http.client.HTTPException)
_CONTEXT_BATCH = 20
_VAR = re.compile(r"\$\{(?P<name>[A-Za-z_][A-Za-z0-9_]*)(?::-(?P<default>[^}]*))?\}")


class LuxPMUnread(Exception):
    """LuxPM could not be asked: no connection configured, or it did not answer."""


def _expand(text: str) -> str:
    return _VAR.sub(
        lambda m: os.environ.get(m.group("name"), m.group("default") or ""), text
    )


def _http_server(entry: object) -> tuple[str, dict[str, str]] | None:
    if not isinstance(entry, dict):
        return None
    url = entry.get("url")
    if entry.get("type") != "http" or not isinstance(url, str) or not url:
        return None
    raw = entry.get("headers")
    headers = (
        {str(k): _expand(str(v)) for k, v in raw.items()}
        if isinstance(raw, dict)
        else {}
    )
    return _expand(url), headers


def _servers(data: object, *path: str) -> object:
    for part in path:
        if not isinstance(data, dict):
            return None
        data = data.get(part)
    return data


def _main_checkout() -> Path:
    try:
        return state_dir().parent.resolve()
    except OSError:
        return project_dir().resolve()


def _committed_mcp_json(main: Path) -> object:
    """The main checkout's `.mcp.json` as committed at HEAD (a worktree's copy is the agent's)."""
    try:
        text = subprocess.run(
            ["git", "-C", str(main), "show", "HEAD:.mcp.json"],
            capture_output=True,
            text=True,
            timeout=4,
            check=False,
        )
    except _GIT_ERRORS:
        return None
    if text.returncode != 0:
        return None
    try:
        return json.loads(text.stdout)
    except ValueError:
        return None


def _scoped(entry: object, scope: str) -> tuple[str, dict[str, str]]:
    found = _http_server(entry)
    if found:
        return found
    kind = entry.get("type") if isinstance(entry, dict) else None
    raise LuxPMUnread(
        f"this project's `luxpm` MCP server ({scope} scope) is of type {kind or 'stdio'}, "
        "which a hook cannot ask: configure it as an http server"
    )


def luxpm_connection() -> tuple[str, dict[str, str]]:
    """(url, headers) of this project's LuxPM MCP server, by Claude Code's own precedence: the
    local scope (`~/.claude.json`, `projects.<main checkout>.mcpServers`), then the project scope
    (the main checkout's `.mcp.json` as committed at HEAD, only when the owner approved it:
    `enabledMcpjsonServers` holds `luxpm`, or `enableAllProjectMcpServers`), then the user scope
    (`~/.claude.json`, `mcpServers`). The first scope that names `luxpm` decides, whatever its
    type: one a hook cannot ask is LuxPMUnread, never a fall-through to the next."""
    home = Path(os.environ.get("HOME") or str(Path.home()))
    try:
        user = json.loads((home / ".claude.json").read_text(encoding="utf-8"))
    except _PAYLOAD_ERRORS:
        user = {}
    main = _main_checkout()
    project_cfg: object = None
    for key in dict.fromkeys(
        (str(main), str(project_dir()), str(project_dir().resolve()))
    ):
        cfg = _servers(user, "projects", key)
        if isinstance(cfg, dict):
            project_cfg = cfg
            break
    local = _servers(project_cfg, "mcpServers", "luxpm")
    if local is not None:
        return _scoped(local, "local")
    approved = isinstance(project_cfg, dict) and (
        project_cfg.get("enableAllProjectMcpServers") is True
        or "luxpm" in (project_cfg.get("enabledMcpjsonServers") or [])
    )
    shared = _servers(_committed_mcp_json(main), "mcpServers", "luxpm")
    if shared is not None and approved:
        return _scoped(shared, "project")
    personal = _servers(user, "mcpServers", "luxpm")
    if personal is not None:
        return _scoped(personal, "user")
    raise LuxPMUnread(
        "no `luxpm` MCP server is configured for this project in Claude Code "
        "(local, approved project, or user scope)"
    )


def _tool_text(
    url: str,
    headers: dict[str, str],
    tool: str,
    arguments: dict[str, object],
    deadline: float,
    refusal_ok: bool = False,
) -> str:
    """The text LuxPM's `tool` answers `arguments` with. Raises LuxPMUnread when LuxPM cannot be
    asked, answers no text, or refuses (`isError`) and `refusal_ok` is not set. Never names the
    server's url: it can carry the key."""
    body = {
        "jsonrpc": "2.0",
        "id": 1,
        "method": "tools/call",
        "params": {"name": tool, "arguments": arguments},
    }
    parts = urllib.parse.urlsplit(url)
    if parts.scheme not in ("http", "https") or not parts.hostname:
        # no part of the url is named: its query, userinfo or an unexpanded variable can hold the key
        raise LuxPMUnread(
            "the luxpm server's url does not start with http:// or https://"
        )
    conn_type = (
        http.client.HTTPSConnection
        if parts.scheme == "https"
        else http.client.HTTPConnection
    )
    path = parts.path or "/"
    if parts.query:
        path += "?" + parts.query
    try:
        left = deadline - time.monotonic()
        if left <= 0:
            raise LuxPMUnread(f"LuxPM did not answer within {_LUXPM_DEADLINE:.0f} s")
        conn = conn_type(parts.hostname, parts.port, timeout=min(_LUXPM_TIMEOUT, left))
        try:
            conn.request(
                "POST",
                path,
                body=json.dumps(body).encode("utf-8"),
                headers={
                    **headers,
                    "Content-Type": "application/json",
                    "Accept": "application/json, text/event-stream",
                },
            )
            resp = conn.getresponse()
            raw = resp.read()
        finally:
            conn.close()
        if resp.status != 200:
            raise LuxPMUnread(f"LuxPM answered HTTP {resp.status}")
        reply = json.loads(raw.decode("utf-8"))
    except _LUXPM_ERRORS as exc:
        raise LuxPMUnread(f"LuxPM did not answer ({exc.__class__.__name__})") from exc
    result = reply.get("result") if isinstance(reply, dict) else None
    content = result.get("content") if isinstance(result, dict) else None
    text = (
        content[0].get("text")
        if isinstance(content, list) and content and isinstance(content[0], dict)
        else None
    )
    if not isinstance(text, str):
        raise LuxPMUnread(f"LuxPM answered {tool} with no text")
    if isinstance(result, dict) and result.get("isError") is True and not refusal_ok:
        raise LuxPMUnread(f"LuxPM refused {tool}: {text[:120]}")
    return text


def _context_call(
    url: str, headers: dict[str, str], keys: list[str], deadline: float
) -> list[dict[str, object]]:
    # a refusal is read below: one unknown key fails the call, and LuxPM names it
    text = _tool_text(
        url, headers, "luxpm_get_context", {"sequence_ids": keys}, deadline, True
    )
    try:
        data = json.loads(text)
    except ValueError:
        # an unknown key fails the whole call, and LuxPM names it: "NOT FOUND: 'AB-9' ..."
        if _NOT_FOUND.search(text):
            return []
        raise LuxPMUnread(f"LuxPM answered an error: {text[:120]}") from None
    issues = data.get("issues") if isinstance(data, dict) else None
    if not isinstance(issues, list):
        one = data.get("issue") if isinstance(data, dict) else None
        issues = [{"issue": one}] if isinstance(one, dict) else []
    return [
        {**i["issue"], "_checklist": i.get("checklist")}
        for i in issues
        if isinstance(i, dict) and isinstance(i.get("issue"), dict)
    ]


def _row(issue: dict[str, object]) -> Issue:
    state_words = str(issue.get("state") or "").split()
    labels = issue.get("labels")
    checklist = issue.get("_checklist")
    return {
        "key": str(issue.get("sequence_id") or "").strip().upper(),
        "title": str(issue.get("title") or ""),
        "state": state_words[-1].lower() if state_words else "",
        "waiting": str(issue.get("waiting_on") or ""),
        "close_summary": str(issue.get("close_summary") or ""),
        "labels": [str(x).strip().lower() for x in labels]
        if isinstance(labels, list)
        else [],
        # as LuxPM holds them: its label filter is exact, case and all
        "labels_exact": [str(x).strip() for x in labels]
        if isinstance(labels, list)
        else [],
        "checklist_titles": [
            str(c.get("title") or "") for c in checklist if isinstance(c, dict)
        ]
        if isinstance(checklist, list)
        else [],
        # the checklist items not yet ticked, by title
        "open_items": [
            str(c.get("title") or "")
            for c in checklist
            if isinstance(c, dict) and not c.get("is_completed")
        ]
        if isinstance(checklist, list)
        else [],
    }


def luxpm_issues(keys: list[str]) -> dict[str, Issue]:
    """{key: {key, title, state, waiting, labels, open_items}} for each key LuxPM knows, read from
    LuxPM now. A key LuxPM does not know is absent. Raises LuxPMUnread when LuxPM cannot be asked,
    or has not answered every call within `_LUXPM_DEADLINE` seconds."""
    wanted = list(dict.fromkeys(k.strip().upper() for k in keys if k.strip()))
    if not wanted:
        return {}
    url, headers = luxpm_connection()
    deadline = time.monotonic() + _LUXPM_DEADLINE
    with _wall_clock(_LUXPM_DEADLINE):
        return _read_issues(url, headers, wanted, deadline)


@contextlib.contextmanager
def _wall_clock(seconds: float) -> Iterator[None]:
    """Raise LuxPMUnread when the block outlasts `seconds` of wall time, however the time is spent
    (a reply that arrives a byte at a time resets every socket timeout). POSIX timer; elsewhere
    the per-call timeouts and the deadline alone bound it."""
    if (
        not hasattr(signal, "setitimer")
        or threading.current_thread() is not threading.main_thread()
    ):
        yield
        return

    def _expired(signum: int, frame: FrameType | None) -> None:
        raise LuxPMUnread(f"LuxPM did not answer within {seconds:.0f} s")

    previous = signal.signal(signal.SIGALRM, _expired)
    signal.setitimer(signal.ITIMER_REAL, seconds)
    try:
        yield
    finally:
        signal.setitimer(signal.ITIMER_REAL, 0)
        signal.signal(signal.SIGALRM, previous)


def _read_issues(
    url: str, headers: dict[str, str], wanted: list[str], deadline: float
) -> dict[str, Issue]:
    rows: dict[str, Issue] = {}
    for n in range(0, len(wanted), _CONTEXT_BATCH):
        batch = wanted[n : n + _CONTEXT_BATCH]
        found = _context_call(url, headers, batch, deadline)
        if not found and len(batch) > 1:
            # one unknown key fails a batch: ask for each alone
            found = [
                i for k in batch for i in _context_call(url, headers, [k], deadline)
            ]
        for issue in found:
            row = _row(issue)
            if row["key"]:
                rows[str(row["key"])] = row
    return rows


_ESCALATION_TITLE = re.compile(
    r"\[[^\]\n]{0,60}\bESCALATION\]|^\[[A-Z][A-Z0-9]{1,15}-\d+\] "
)


def is_escalation(title: object, labels: list[str]) -> bool:
    """An escalation: labelled `fleet-escalation`, `escalation` or `escalation-from-<project>`,
    or titled `[<guard> ESCALATION] …` or, relayed into a guard's project, `[<KEY>] …`."""
    if any(
        x in ("fleet-escalation", "escalation") or x.startswith("escalation-from-")
        for x in labels
    ):
        return True
    return bool(_ESCALATION_TITLE.search(str(title or "")))


def row_labels(row: Issue | None) -> list[str]:
    labels = row.get("labels") if row else None
    return [str(x) for x in labels] if isinstance(labels, list) else []


def own_issue_key(root: Path) -> str:
    """The issue this checkout is the worktree of (its branch is `worktree-<KEY>`), else ''."""
    try:
        branch = subprocess.check_output(
            ["git", "-C", str(root), "rev-parse", "--abbrev-ref", "HEAD"],
            text=True,
            stderr=subprocess.DEVNULL,
            timeout=4,
        ).strip()
    except _GIT_ERRORS:
        return ""
    return branch[len("worktree-") :] if branch.startswith("worktree-") else ""


# ── which release writing guides each session has read in full ─────────────────────────────────────
# release-docs-read-guides: a change log or release notes file is written after its writing guides
# were read this session, so the guide is the template, not the previous release's file.


def guides_read_path() -> Path:
    return state_dir() / ".release-guides-read.json"


def record_guide_read(guide: str) -> bool:
    """Remember that this session read `guide` in full. False when it cannot be written."""
    return _record_term(guides_read_path(), guide)


def guides_read() -> list[str]:
    return _read_terms(guides_read_path()).get(session_id(), [])


def guides_writable() -> bool:
    return _writable(guides_read_path())


def commits_path() -> Path:
    """Every commit an agent session made here, by session, kept until it reaches upstream. Not
    the LuxPM ledger: that one is emptied once the work is logged, and the push guard still has to
    know whose commits are unpushed afterwards."""
    return state_dir() / ".session-commits.json"


def record_session_commit(sha: str, subject: str) -> None:
    entry: dict[str, object] = {"sha": sha, "subject": subject, "session": session_id()}

    def add(data: object) -> list[dict[str, object]]:
        entries = _entries(data)
        if any(e.get("sha") == sha for e in entries):
            return entries
        return [*entries, entry][-500:]

    _update_json(commits_path(), [], add)


# ── who this agent is, and the owner orders it was given ───────────────────────────────────────────
# The owner names each session for its job: `[<repo> <role>]`, e.g. `[shop mypy]`. Claude Code
# writes that name into the session's transcript as an `agent-name` record, again and again as the
# session goes on, so the end of the file holds the current one. An owner order is a LuxPM issue the
# OWNER labelled `owner-order` (and `agent:<role>` for one role), or the note of a `/fleet-start
# <note>` the owner typed; it is the agent's work ahead of every queue.

_NAME_RECORD = '"agent-name"'
_NAME_TAIL = 4 * 1024 * 1024


def _name_in(lines: list[str]) -> str:
    name = ""
    for line in lines:
        if _NAME_RECORD not in line:
            continue
        try:
            rec = json.loads(line)
        except _PAYLOAD_ERRORS:
            continue
        if not isinstance(rec, dict) or rec.get("type") != "agent-name":
            continue
        got = rec.get("agentName")
        if isinstance(got, str) and got.strip():
            name = got.strip()
    return name


def agent_name(transcript: str) -> str:
    """The name the owner gave this session (the last `agent-name` record), '' when it has none."""
    if not transcript:
        return ""
    try:
        with open(transcript, "rb") as fh:
            fh.seek(0, os.SEEK_END)
            size = fh.tell()
            fh.seek(max(0, size - _NAME_TAIL))
            tail = fh.read().decode("utf-8", "replace").splitlines()
            if size > _NAME_TAIL:
                tail = tail[1:]  # the first line of a tail is cut
            name = _name_in(tail)
            if name or size <= _NAME_TAIL:
                return name
            fh.seek(0)
            return _name_in(fh.read().decode("utf-8", "replace").splitlines())
    except OSError:
        return ""


# ── handoffs between the agents of one repo ──────────────────────────────────────────────────────
# A repo with more than one agent declares their roles in its committed `.luxarch.toml`:
# `[agents]` `roles = ["backend", "ios"]`. One agent hands work to another as an issue in the
# repo's own project labelled `agent:<their role>`, state todo, `waiting_on: "<their role> agent:
# <the step>"`; a reply owed on an existing issue is the same label and waiting_on. Each agent's
# `/fleet-start` lists the issues labelled with its role. The roles are read from the main
# checkout as committed at HEAD: a worktree's copy is the agent's own.
_HANDOFF_WAIT = re.compile(
    r"(?P<role>[A-Za-z0-9][A-Za-z0-9 _-]{0,40}?) agent:\s*\S.*", re.DOTALL
)
_ROLES_LINE = re.compile(r"^\s*roles\s*=\s*\[(?P<items>[^\]]*)\]", re.MULTILINE)


def role_name(raw: str) -> str:
    """A role as one word: lower-cased, spaces and underscores as `-` (`iOS app` -> `ios-app`)."""
    return re.sub(r"[\s_]+", "-", raw.strip().lower()).strip("-")


HANDOFF_LABEL = "agent:"


def _toml() -> ModuleType | None:
    """The standard library's TOML reader (Python 3.11 and later), or None before it."""
    try:
        return importlib.import_module("tomllib")
    except ImportError:
        return None


def declared_roles() -> list[str]:
    """The agent roles the repo declares (`[agents] roles`), each as `role_name` gives it; []
    when none."""
    try:
        main = state_dir().parent
        shown = subprocess.run(
            ["git", "-C", str(main), "show", "HEAD:.luxarch.toml"],
            capture_output=True,
            text=True,
            timeout=4,
            check=False,
        )
    except _GIT_ERRORS:
        return []
    if shown.returncode != 0:
        return []
    roles = _roles_in(shown.stdout)
    return [r for r in (role_name(str(x)) for x in roles) if r]


def _roles_in(text: str) -> list[object]:
    """`[agents] roles` from the TOML text: read by the TOML reader where Python has one, else by
    the one-line form `roles = ["a", "b"]` under `[agents]` (Python 3.9 and 3.10, a Mac's own)."""
    toml = _toml()
    if toml is not None:
        try:
            data = toml.loads(text)
        except ValueError:
            return []
        agents = data.get("agents") if isinstance(data, dict) else None
        roles = agents.get("roles") if isinstance(agents, dict) else None
        return roles if isinstance(roles, list) else []
    section = re.search(
        r"^\[agents\]\s*$(?P<body>.*?)(?=^\[|\Z)", text, re.MULTILINE | re.DOTALL
    )
    m = _ROLES_LINE.search(section.group("body")) if section else None
    if not m:
        return []
    return re.findall(r"[\"']([^\"']*)[\"']", m.group("items"))


def handoff_to(waiting: object, own_role: str, roles: list[str]) -> str:
    """The role a `waiting_on` hands to (`<role> agent: <step>`) when it is a declared role other
    than this session's own, which must be declared too; '' otherwise."""
    m = _HANDOFF_WAIT.fullmatch(str(waiting or "").strip())
    own = role_name(own_role)
    if not m or not own or own not in roles:
        return ""
    role = role_name(m.group("role"))
    return role if role in roles and role != own else ""


def agent_role(name: str) -> str:
    """The role in `[<repo> <role>]`: the words after the first, without a `-` separator, joined
    by `-` and lower-cased (`[shop - luxarch]` -> `luxarch`). '' for a name of one word."""
    words = [w for w in name.strip().strip("[]").split() if w != "-"]
    return "-".join(w.lower() for w in words[1:])
